import React, { useState, useEffect } from 'react';

const VoiceWeb = () => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState([]);
  const [currentLanguage, setCurrentLanguage] = useState('en-IN');
  const [step, setStep] = useState('init');

  // Exact UI and original voice engine settings
  const speak = (text, lang = currentLanguage) => {
    window.speechSynthesis.cancel(); // Clear queue
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = lang;
    utterance.rate = 0.9; // Natural pace
    utterance.pitch = 1.0;
    window.speechSynthesis.speak(utterance);
    setTranscript(prev => [...prev, { role: 'System', text }]);
  };

  const startListening = () => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) return alert("Browser not supported");

    const recognition = new SpeechRecognition();
    recognition.lang = currentLanguage;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);

    recognition.onresult = (event) => {
      const result = event.results[0][0].transcript.toLowerCase();
      setTranscript(prev => [...prev, { role: 'You', text: result }]);
      handleConversation(result);
    };

    recognition.start();
  };

  const handleConversation = (input) => {
    if (step === 'init') {
      if (input.includes('telugu') || input.includes('తెలుగు')) {
        setCurrentLanguage('te-IN');
        setStep('service');
        speak("తెలుగు సెలెక్ట్ చేసుకోబడినది. మీకు ఏ సర్వీస్ కావాలో సెలెక్ట్ చేసుకోండి?", 'te-IN');
      } else {
        setStep('service');
        speak("English selected. Which service do you need?");
      }
    } else if (step === 'service') {
      if (input.includes('booking') || input.includes('బుకింగ్')) {
        setStep('route');
        const msg = currentLanguage === 'te-IN' 
          ? "మీరు ఎక్కడి నుంచి ఎక్కడికి ప్రయాణం చేయాలనుకుంటున్నారు?"
          : "Understood. Where is your departure and destination city?";
        speak(msg);
      }
    } else if (step === 'route') {
      setStep('date');
      const msg = currentLanguage === 'te-IN'
        ? "మీరు ఎప్పుడు ప్రయాణం చేయాలనుకుంటున్నారు?"
        : "What is your preferred travel date and time?";
      speak(msg);
    } else if (step === 'date') {
      const pnr = "SKY" + Math.floor(1000 + Math.random() * 9000);
      const msg = currentLanguage === 'te-IN'
        ? `మీ బుకింగ్ పూర్తయింది. మీ పీ ఎన్ ఆర్ నంబర్ ${pnr}.`
        : `Thank you. Your booking is confirmed. Your PNR is ${pnr}.`;
      speak(msg);
      setStep('done');
    }
  };

  // Immediate greeting when they click the UI
  const handleInitialClick = () => {
    if (step === 'init' && transcript.length === 0) {
      speak("Hello, Welcome to SkySync AI. Please choose your language.");
    }
    startListening();
  };

  return (
    <div style={{ display: 'flex', height: '100vh', background: '#f8fafc', fontFamily: 'Inter, sans-serif' }}>
      {/* SIDEBAR */}
      <div style={{ width: '260px', background: 'white', padding: '25px', borderRight: '1px solid #e2e8f0' }}>
        <h3 style={{ color: '#1d4ed8' }}>SKY-SYNC AI</h3>
        <div style={{ marginTop: '40px', color: '#64748b', fontSize: '13px' }}>
          <p>FLIGHT SERVICES</p>
          <ol style={{ paddingLeft: '15px', lineHeight: '2.2' }}>
            <li>Booking</li><li>Status</li><li>Check-in</li><li>Baggage</li>
          </ol>
        </div>
      </div>

      {/* MAIN CONVERSATION AREA */}
      <div style={{ flex: 1, padding: '30px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
        <div style={{ background: 'white', borderRadius: '24px', padding: '40px', textAlign: 'center', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}>
          <button 
            onClick={handleInitialClick}
            style={{ width: '120px', height: '120px', borderRadius: '50%', border: 'none', background: isListening ? '#eff6ff' : '#1d4ed8', cursor: 'pointer', transition: '0.3s' }}
          >
            <span style={{ fontSize: '40px' }}>{isListening ? '🌊' : '🎙️'}</span>
          </button>
          <p style={{ marginTop: '15px', fontWeight: 'bold', color: '#1d4ed8' }}>{isListening ? 'LISTENING...' : 'TAP TO START'}</p>
        </div>

        <div style={{ flex: 1, background: 'white', borderRadius: '24px', padding: '25px', overflowY: 'auto', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}>
          <p style={{ fontWeight: 'bold', color: '#1d4ed8', marginBottom: '15px' }}>Live Transcript</p>
          {transcript.map((t, i) => (
            <div key={i} style={{ marginBottom: '15px', background: t.role === 'You' ? '#f1f5f9' : 'transparent', padding: '10px', borderRadius: '10px' }}>
              <small style={{ color: '#1d4ed8', fontWeight: 'bold' }}>{t.role}</small>
              <p style={{ margin: '5px 0' }}>{t.text}</p>
            </div>
          ))}
        </div>
      </div>

      {/* RIGHT SIDEBAR */}
      <div style={{ width: '300px', padding: '25px' }}>
        <div style={{ background: '#1d4ed8', color: 'white', padding: '20px', borderRadius: '20px', textAlign: 'center' }}>
          <h2>28°C</h2>
          <p>Hyderabad - Sunny</p>
        </div>
      </div>
    </div>
  );
};

export default VoiceWeb;
